    }

    /// Consulta el array de acuerdos (agreements) y devuelve la wallet del siguiente árbitro que según el orden en validArbiters, se asignaría al siguiente acuerdo.
    /// La asignación de árbitros a los acuerdos debe hacerse uno a uno, en orden, es decir, al acuerdo 0 debe asignarse el 
    /// primer árbitro válido (o sea 0x31e331E751e490ef39e8B269399a76f483b2b5Af), al acuerdo 1 debe asignarse el segundo árbitro
    /// válido (o sea 0x3069EBaEcA68b5f5E113e0d4Fc3155Bd0Bf4926B), al acuerdo 2 el tercer árbitro (0x6c83C41cc7226AFb36ee66814cAbb952c9E89EC7),
    /// para el acuerdo 3 tocaría volver al inicio del listado de árbitros, ya que por ahora hay 3, y se le asignaría el primero árbitro.
    /// En caso de que entre un cuarto, quinto, sexto o "N" árbitros desde la función "addValidArbiterIfNotExists", deberán irse agregando al final
    /// del listado de árbitros válidos y, asímismo, se les deberán ir asignando acuerdos. 
    function getNextArbiter() public view returns (address) {
        //Aquí se debe consultar el array agreements, tomar el último acuerdo, obtener la wallet del árbitro asignado, con esa wallet obtener su orden o ID de array
        //de esa wallet en el array validArbiters, y, finalmente, de dicho array obtener la siguiente wallet de árbitro que se asignaría al siguiente acuerdo.

        uint256 numArbiters = validArbiters.length;
        require(numArbiters > 0, "No hay arbitros validos disponibles.");

        // Si no hay acuerdos creados aún, asignar el primer árbitro
        if (agreements.length == 0) {
            return validArbiters[0];
        }

        // Obtener el árbitro asignado en el último acuerdo
        Agreement memory lastAgreement = agreements[agreements.length - 1];
        address lastArbiter = lastAgreement.arbitrator;

        // Encontrar el índice del último árbitro en el array validArbiters
        uint256 lastArbiterIndex;
        for (uint256 i = 0; i < numArbiters; i++) {
            if (validArbiters[i] == lastArbiter) {
                lastArbiterIndex = i;
                break;
            }
        }

        // Calcular el índice del próximo árbitro (circular)
        uint256 nextArbiterIndex = (lastArbiterIndex + 1) % numArbiters;

        // Retornar la dirección del próximo árbitro
        return validArbiters[nextArbiterIndex];

    }

    /// @notice Normaliza un timestamp a la medianoche.
    /// @param timestamp Timestamp a normalizar.
    /// @return El timestamp normalizado.
    function normalizeToDay(uint256 timestamp) internal pure returns (uint256) {
        return (timestamp / DAY_IN_SECONDS) * DAY_IN_SECONDS;
    }

    /// @notice Verifica si un árbitro es válido.
    /// @param _arbiter Dirección del árbitro.
    /// @return true si el árbitro es válido, de lo contrario false.
    function isValidArbiter(address _arbiter) internal view returns (bool) {
        for (uint i = 0; i < validArbiters.length; i++) {
            if (validArbiters[i] == _arbiter) {
                return true;
            }
        }
        return false;
    }

    /// @notice Permite a los árbitros agregar otros árbitros válidos.
    /// @param _arbiter Dirección del nuevo árbitro.
    function addValidArbiterIfNotExists(address _arbiter) external {
        require(isValidArbiter(msg.sender), "Solo un arbitro valido puede agregar nuevos arbitros.");
        require(!isValidArbiter(_arbiter), "El arbitro ya esta registrado.");
        validArbiters.push(_arbiter);
    }

    // Evento que emitirá el ID del nuevo acuerdo creado
    event NewAgreementCreated(uint256 indexed agreementId);

    /// @notice Crea un nuevo acuerdo, incluyendo el cobro de fees a DAO y árbitros.
    /// @param _serviceProvider Dirección del proveedor del servicio.
    /// @param _servicePayer Dirección del pagador del servicio.
    /// @param _startDate Fecha de inicio del acuerdo.
    /// @param _endDate Fecha de fin del acuerdo.
    /// @param _numHours Número de horas acordadas
    /// @param _amount Monto total del acuerdo en USDC (incluye fees).
    /// @return El ID del acuerdo creado.
    function newAgreement(
        address _serviceProvider,
        address _servicePayer,
        uint256 _startDate,
        uint256 _endDate,
        uint256 _numHours,
        uint256 _amount
    ) external returns (uint) {
        uint256 normalizedStartDate = normalizeToDay(_startDate);
        uint256 normalizedEndDate = normalizeToDay(_endDate);
        uint256 currentDate = normalizeToDay(block.timestamp);

        require(_serviceProvider != _servicePayer, "Las wallets de proveedor y pagador no pueden ser iguales.");
        require(normalizedStartDate >= currentDate, "Fecha de inicio debe ser hoy o mayor");
        require(normalizedEndDate >= normalizedStartDate, "Fecha de fin debe ser mayor o igual a la de inicio");
        require(_amount > FEE_ARBITRATION + FEE_DAO, "Monto insuficiente para cubrir fees.");

        // Obtener el próximo árbitro 
        address nextArbiter = getNextArbiter();

        // Transferir USDC del pagador al contrato
        usdcToken.transferFrom(msg.sender, address(this), _amount);

        agreements.push(Agreement({
            serviceProvider: _serviceProvider,
            servicePayer: _servicePayer,
            arbitrator: nextArbiter,
            startDate: normalizedStartDate,
            endDate: normalizedEndDate,
            numHours: _numHours,
            amount: _amount - FEE_ARBITRATION - FEE_DAO,
            spaAgree: true,
            sprAgree: true,
            arbitrationState: ArbitrationState.NoArbitration
        }));

        // Cobrar fees
        require(usdcToken.transfer(daoTreasury, FEE_DAO), "Transferencia al tesoro DAO fallida.");
        distributeFees(FEE_ARBITRATION);

        //return agreements.length - 1;

        uint256 agreementId = agreements.length - 1;
        // Emitimos el evento con el ID del acuerdo
        emit NewAgreementCreated(agreementId);
        return agreementId;
    
    }

    /// @dev Distribuye los fees de arbitraje entre árbitros válidos.
    function distributeFees(uint256 arbitrationFee) internal {
        uint256 numArbiters = validArbiters.length;
        require(numArbiters > 0, "No hay arbitros validos.");
        uint256 feePerArbiter = arbitrationFee / numArbiters;

        for (uint256 i = 0; i < numArbiters; i++) {
            usdcToken.transfer(validArbiters[i], feePerArbiter);
        }
    }

    /// @notice Marca acuerdo o desacuerdo por parte únicamente del pagador o del proveedor.
    /// @param _id ID del acuerdo.
    /// @param agree Estado, solo hay dos posibles pues es booleano: "de acuerdo" (true) o "en desacuerdo" (false).
    function setAgreement(uint _id, bool agree) external {
        Agreement storage agreement = agreements[_id];

        uint256 currentDate = normalizeToDay(block.timestamp);
        //Solo pueden cambiar entre acuerdo y desacuerdo si no ha llegado fecha fin y si hay monto. Sino, no tiene ya sentido que haya desacuerdos, pues el acuerdo ya se pagó.
        require(currentDate <= agreement.endDate, "Acuerdo finalizado. Solo puede cambiar acuerdo/desacuerdo si acuerdo esta vigente, si aun no finaliza.");
        require(agreement.amount > 0, "Acuerdo sin monto.");   

        if (msg.sender == agreement.servicePayer) {
            agreement.spaAgree = agree;
            agreement.arbitrationState = agree == false ? ArbitrationState.Arbitration : ArbitrationState.NoArbitration;
        } else if (msg.sender == agreement.serviceProvider) {
            agreement.sprAgree = agree;
            agreement.arbitrationState = agree == false ? ArbitrationState.Arbitration : ArbitrationState.NoArbitration;
        } else {
            revert("No autorizado");
        }
    }

    /// @notice Resuelve un desacuerdo por parte del árbitro.
    /// @param _id ID del acuerdo.
    /// @param inFavorOfProvider Decisión a favor del proveedor.
    function resolveDisagreement(uint _id, bool inFavorOfProvider) external {
        Agreement storage agreement = agreements[_id];

        require(msg.sender == agreement.arbitrator, "Solo el arbitro asignado puede resolver.");
        require(agreement.amount > 0, "Acuerdo sin monto.");
        require(agreement.spaAgree == false || agreement.sprAgree == false, "No hay desacuerdo que resolver, ambas partes estan de acuerdo.");
        require(agreement.arbitrationState == ArbitrationState.Arbitration, "No hay desacuerdo que resolver, no esta en estado de arbitraje.");

        if (inFavorOfProvider) {
            agreement.arbitrationState = ArbitrationState.ResolvedSPR;
            usdcToken.transfer(agreement.serviceProvider, agreement.amount);
        } else {
            agreement.arbitrationState = ArbitrationState.ResolvedSPA;
            usdcToken.transfer(agreement.servicePayer, agreement.amount);
        }

        agreement.amount = 0;
    }

    /*/// @notice Automatización diaria para procesar acuerdos.
    function executeAutomation() external {
        uint256 currentDate = normalizeToDay(block.timestamp);

        for (uint i = 0; i < agreements.length; i++) {
            Agreement storage agreement = agreements[i];

            if (agreement.amount > 0 && agreement.spaAgree && agreement.sprAgree && currentDate >= agreement.endDate) {
                usdcToken.transfer(agreement.serviceProvider, agreement.amount);
                agreement.amount = 0;
            }
        }
    }*/

    /// @notice Procesa un lote de acuerdos.
    /// @param agreementIds Array con los IDs de los acuerdos a procesar.
    function processAgreementsBatch(uint[] memory agreementIds) public {
        require(msg.sender == AGREEMENTS_PAYER, "Solo la wallet autorizada para Agreements Payer puede procesar y pagar acuerdos.");
        
        uint256 currentDate = normalizeToDay(block.timestamp);

        for (uint i = 0; i < agreementIds.length; i++) {

            uint256 agreementId = agreementIds[i];
            // Validar si el acuerdo existe
            if (agreementId >= agreements.length) {
                continue; // Si el ID no existe, pasar al siguiente
            }

            Agreement storage agreement = agreements[agreementId];

            if (agreement.spaAgree && agreement.sprAgree && agreement.arbitrationState == ArbitrationState.NoArbitration && 
                agreement.amount > 0 && currentDate >= agreement.endDate) {
                usdcToken.transfer(agreement.serviceProvider, agreement.amount);
                agreement.amount = 0; // Marca el acuerdo como pagado
            }
        }
    }

}

contracts/WMCAgreementManagement.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @title WMCServiceManagement - Gestión de acuerdos con fees para DAO y árbitros.
/// @notice Permite crear, gestionar y finalizar acuerdos entre proveedores y pagadores de servicios.
/// @dev Integra pagos de fees fijos para DAO y árbitros en el proceso de creación de acuerdos.

interface IERC20 {
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

contract WMCAgreementManagement {
    IERC20 public usdcToken;

    // Enum para representar los estados de un acuerdo
    enum Estado { Contratado, EnCurso, Finalizado, EnDisputa, Reembolsado, Desembolsado }

    // Estructura para almacenar la información de un acuerdo
    struct Agreement {
        address serviceProvider; // Wallet del proveedor del servicio
        address servicePayer;    // Wallet del pagador del servicio
        address arbitrator;      // Wallet del árbitro asignado
        uint256 startDate;       // Fecha de inicio del acuerdo
        uint256 endDate;         // Fecha de fin del acuerdo
        uint256 amount;          // Monto del acuerdo en USDC
        Estado estado;           // Estado actual del acuerdo
        bool spaAgree;           // Aprobación del pagador
        bool sprAgree;           // Aprobación del proveedor
    }

    Agreement[] public agreements;        // Lista de acuerdos
    address[] public validArbiters;       // Lista de árbitros válidos
    //uint256 private numArbiters; // Variable temporal para almacenar el número de árbitros válidos
    address public daoTreasury = 0xAC9Adcccd19Ea5A05e5A5A5F37C8c02dd9a2ce9C; // Direccion quemada del tesoro DAO
    uint constant DISPUTE_PERIOD = 604800; // Periodo de disputa en segundos (7 días)
    uint constant DAY_IN_SECONDS = 86400; // Duración de un día en segundos
    uint256 private constant FEE_ARBITRATION = 1.5 * 10 ** 6; // USDC $1.5
    uint256 private constant FEE_DAO = 1 * 10 ** 6; // USDC $1

    /// @dev Constructor para inicializar el contrato.
    /// @param _usdcTokenAddress Dirección del token USDC.
    constructor(address _usdcTokenAddress) {
        usdcToken = IERC20(_usdcTokenAddress);
        // Quemar las wallets de los árbitros iniciales
        validArbiters.push(0x0aE67cE895B26BdAb093542c8783b985a243E60C);
        validArbiters.push(0x1bD61554e343F88F23a094cCB22D83031B3F0adb);
        validArbiters.push(0xB0eA724275BeA77959622B58E97A9d26D4B44Ea2);
        //numArbiters = validArbiters.length; // Inicializamos el número de árbitros
    }

    /// @notice Normaliza un timestamp a la medianoche.
    /// @param timestamp Timestamp a normalizar.
    /// @return El timestamp normalizado.
    function normalizeToDay(uint256 timestamp) internal pure returns (uint256) {
        return (timestamp / DAY_IN_SECONDS) * DAY_IN_SECONDS;
    }

    /// @notice Verifica si un árbitro es válido.
    /// @param _arbiter Dirección del árbitro.
    /// @return true si el árbitro es válido, de lo contrario false.
    function isValidArbiter(address _arbiter) internal view returns (bool) {
        for (uint i = 0; i < validArbiters.length; i++) {
            if (validArbiters[i] == _arbiter) {
                return true;
            }
        }
        return false;
    }

    function addValidArbiterIfNotExists(address _arbiter) external {
        require(isValidArbiter(msg.sender), "Solo un arbitro valido puede agregar nuevos arbitros.");
        require(!isValidArbiter(_arbiter), "El arbitro ya esta registrado.");
        validArbiters.push(_arbiter);
        //numArbiters = validArbiters.length; // Actualizamos el número de árbitros
    }

    /// @dev Función auxiliar para distribuir los fees de arbitraje entre árbitros válidos.
    function distributeFees(uint256 arbitrationFee) internal {
        uint256 numArbiters = validArbiters.length;
        require(numArbiters > 0, "No hay arbitros validos.");
        uint256 feePerArbiter = arbitrationFee / numArbiters;

        for (uint256 i = 0; i < numArbiters; i++) {
            require(
                usdcToken.transfer(validArbiters[i], feePerArbiter),
                "Transferencia a arbitro fallida."
            );
        }
    }

    /// @notice Crea un nuevo acuerdo, incluyendo el cobro de fees a DAO y árbitros.
    /// @param _serviceProvider Dirección del proveedor del servicio.
    /// @param _servicePayer Dirección del pagador del servicio.
    /// @param _arbitrator Dirección del árbitro asignado.
    /// @param _startDate Fecha de inicio del acuerdo.
    /// @param _endDate Fecha de fin del acuerdo.
    /// @param _amount Monto total del acuerdo en USDC (incluye fees).
    /// @return El ID del acuerdo creado.
    function newAgreement(
        address _serviceProvider,
        address _servicePayer,
        address _arbitrator,
        uint256 _startDate,
        uint256 _endDate,
        uint256 _amount
    ) external returns (uint) {
        uint256 normalizedStartDate = normalizeToDay(_startDate);
        uint256 normalizedEndDate = normalizeToDay(_endDate);
        uint256 normalizedCurrentDate = normalizeToDay(block.timestamp);

        require(_serviceProvider != _servicePayer, "Las wallets de proveedor y pagador no pueden ser iguales.");
        require(normalizedStartDate >= normalizedCurrentDate, "Fecha de inicio debe ser hoy o mayor");
        require(normalizedStartDate <= normalizedCurrentDate + 1 weeks, "Fecha de inicio no puede ser mayor a una semana desde hoy");
        require(normalizedEndDate >= normalizedStartDate, "Fecha de fin debe ser mayor o igual a la de inicio");
        require(_amount > 0, "El valor del servicio debe ser mayor a 0");
        require(isValidArbiter(_arbitrator), "El arbitro no es valido");
        require(_amount > FEE_ARBITRATION + FEE_DAO, "Monto insuficiente para cubrir fees.");

        // Capturar error en la llamada externa transferFrom
        try usdcToken.transferFrom(msg.sender, address(this), _amount) returns (bool success) {
            require(success, "Transferencia de USDC fallida");
        } catch {
            revert("Error al transferir USDC");
        }

        // Distribuir los fees
        distributeFees(FEE_ARBITRATION);
        require(usdcToken.transfer(daoTreasury, FEE_DAO), "Transferencia al tesoro DAO fallida.");

        agreements.push(Agreement({
            serviceProvider: _serviceProvider,
            servicePayer: _servicePayer,
            arbitrator: _arbitrator,
            startDate: normalizedStartDate,
            endDate: normalizedEndDate,
            amount: _amount - FEE_ARBITRATION - FEE_DAO,
            estado: Estado.Contratado,
            spaAgree: true,
            sprAgree: true
        }));

        return agreements.length - 1;
    }

    function updateState(uint _id) external {
        Agreement storage agreement = agreements[_id];
        uint256 normalizedCurrentDate = normalizeToDay(block.timestamp);

        if (agreement.estado == Estado.Contratado && normalizedCurrentDate >= agreement.startDate) {
            agreement.estado = Estado.EnCurso;
        }

        if (agreement.estado == Estado.EnCurso && normalizedCurrentDate >= agreement.endDate) {
            agreement.estado = Estado.Finalizado;
        }
    }

    function setAgreement(uint _id, bool agree) external {
        Agreement storage agreement = agreements[_id];

        if (msg.sender == agreement.servicePayer) {
            agreement.spaAgree = agree;
        } else if (msg.sender == agreement.serviceProvider) {
            agreement.sprAgree = agree;
        } else {
            revert("No autorizado");
        }

        if (!agreement.spaAgree || !agreement.sprAgree) {
            agreement.estado = Estado.EnDisputa;
        }
    }

    function resolveDispute(uint _id, bool inFavorOfProvider) external {
        Agreement storage agreement = agreements[_id];

        require(msg.sender == agreement.arbitrator, "Solo el arbitro asignado puede resolver la disputa");
        require(agreement.estado == Estado.EnDisputa, "No hay disputa para resolver");

        if (inFavorOfProvider) {
            agreement.estado = Estado.Desembolsado;
            require(usdcToken.transfer(agreement.serviceProvider, agreement.amount), "Transferencia al SPR fallida");
        } else {
            agreement.estado = Estado.Reembolsado;
            require(usdcToken.transfer(agreement.servicePayer, agreement.amount), "Reembolso al SPA fallido");
        }

        agreement.amount = 0;
    }

    function finalizeAutomatically(uint _id) external {
        Agreement storage agreement = agreements[_id];
        uint256 normalizedCurrentDate = normalizeToDay(block.timestamp);
        
        require(agreement.estado == Estado.Finalizado, "El acuerdo no esta en Finalizado");
        require(normalizedCurrentDate >= agreement.endDate + DISPUTE_PERIOD, "No ha pasado el periodo de disputa");
        require(agreement.spaAgree && agreement.sprAgree, "Ambas partes deben estar de acuerdo");

        agreement.estado = Estado.Desembolsado;
        require(usdcToken.transfer(agreement.serviceProvider, agreement.amount), "Transferencia al SPR fallida");
        agreement.amount = 0;
    }

    function getCurrentTimestamp() external view returns (uint256) {
        return normalizeToDay(block.timestamp);
    }
    
}

contracts/WMCWUNRewardDistributor.sol.content:
// SPDX-License-Identifier: All Rights Reserved
// © 2025, WorkMarketCap. Todos los derechos reservados.

pragma solidity ^0.8.24;

/**
 * @title WMCWUNRewardDistributor
 * @dev Smart contract para distribuir tokens WUN como recompensas por registro y ejecución de acuerdos.
 *
 * Nota importante:
 * - Se mintearon inicialmente 100,000,000 WUN en total (100 millones de tokens con 18 decimales).
 * - 50,000,000 WUN (50 millones) están inaccesibles en una wallet cuya clave privada se perdió.
 * - Este contrato opera con los 50,000,000 WUN restantes, de los cuales 10,000,000 WUN (20%) se usarán para distribución inicial.
 */
contract WMCWUNRewardDistributor {
    address public owner; // Dirección del propietario del contrato.
    address public immutable tokenContract = 0x6aA78f6077647d90ef5E5F1d432F9C2B66FF0182; // Dirección fija del contrato del token WUN.
    uint256 public totalDistributed; // Cantidad total de tokens distribuidos por este contrato.

    // Máximos y recompensas
    uint256 public constant MAX_TOKENS_GLOBAL = 100_000_000 * 10**18; // Máximo total de WUN minteados originalmente.
    uint256 public constant TOKENS_BURNED_OR_LOST = 50_000_000 * 10**18; // WUN perdidos o inaccesibles en la wallet bloqueada.
    uint256 public constant MAX_CIRCULATING_TOKENS = MAX_TOKENS_GLOBAL - TOKENS_BURNED_OR_LOST; // Máximo de WUN en circulación (50 millones).
    uint256 public constant INITIAL_DISTRIBUTION = 10_000_000 * 10**18; // Tokens reservados para distribución inicial (10 millones).
    uint256 public registrationReward = 10_000 * 10**18; // Recompensa fija de 10,000 WUN por registro.
    uint256 public rewardPercentage = 5; // Porcentaje (5%) del valor del acuerdo que se recompensa en WUN.

    mapping(address => bool) public registeredUsers; // Registro para evitar recompensar múltiples veces a la misma wallet por registro.

    // Eventos para monitorear las operaciones de distribución y actualizaciones de parámetros
    event TokensDistributed(address indexed user, uint256 amount, string reason);
    event RegistrationRewardUpdated(uint256 newReward);
    event RewardPercentageUpdated(uint256 newPercentage);

    // Modificador para restringir funciones al propietario del contrato
    modifier onlyOwner() {
        require(msg.sender == owner, "Solo el propietario puede ejecutar esta funcion");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    /**
     * @dev Recompensa a un usuario con tokens WUN al registrarse en la plataforma.
     * @param user Dirección del usuario que se está registrando.
     */
    function rewardRegistration(address user) external onlyOwner {
        require(!registeredUsers[user], "El usuario ya esta registraddo");
        require(totalDistributed + registrationReward <= INITIAL_DISTRIBUTION, "Se ha superado el limite maximo de distribucion");

        // Transferencia de tokens WUN desde este contrato a la wallet del usuario registrado.
        IERC20(tokenContract).transfer(user, registrationReward);

        // Marcar al usuario como registrado para evitar recompensas duplicadas.
        registeredUsers[user] = true;
        totalDistributed += registrationReward;

        emit TokensDistributed(user, registrationReward, "Registration");
    }

    /**
     * @dev Recompensa a ambas partes involucradas en la ejecución de un acuerdo con un porcentaje del valor del acuerdo.
     * @param freelancer Dirección del proveedor de servicio (Service Provider - SPR o freelancer) que participa en el acuerdo.
     * @param company Dirección del pagador del servicio (Service Payer - SPA o empresa) aque participa en el acuerdo.
     * @param agreementValue Valor del acuerdo en USDT (o el token base equivalente).
     */
    function rewardAgreement(address freelancer, address company, uint256 agreementValue) external onlyOwner {
        uint256 reward = (agreementValue * rewardPercentage / 100) * 10**18; // Calcular recompensa

        require(totalDistributed + (2 * reward) <= INITIAL_DISTRIBUTION, "Se ha superado el limite maximo de distribucion");

        // Transferir recompensa al SPR.
        IERC20(tokenContract).transfer(freelancer, reward);
        // Transferir recompensa a la SPA.
        IERC20(tokenContract).transfer(company, reward);

        totalDistributed += 2 * reward;

        emit TokensDistributed(freelancer, reward, "Agreement-SPR");
        emit TokensDistributed(company, reward, "Agreement-SPA");
    }

    /**
     * @dev Actualiza la cantidad de tokens que se recompensa a un usuario por registrarse.
     * @param newReward Nueva cantidad de tokens WUN para recompensas de registro.
     * - Ejemplo: Si `newReward = 5000 * 10**18`, el nuevo valor será 5,000 WUN.
     */
    function updateRegistrationReward(uint256 newReward) external onlyOwner {
        registrationReward = newReward;
        emit RegistrationRewardUpdated(newReward);
    }

    /**
     * @dev Actualiza el porcentaje de recompensa que se otorga por los acuerdos ejecutados.
     * @param newPercentage Nuevo porcentaje de recompensa por acuerdo.
     * - Ejemplo: Si `newPercentage = 3`, la recompensa será el 3% del valor del acuerdo.
     */
    function updateRewardPercentage(uint256 newPercentage) external onlyOwner {
        rewardPercentage = newPercentage;
        emit RewardPercentageUpdated(newPercentage);
    }

    /**
     * @dev Transferir todos los tokens restantes del contrato a la  wallet del propietario.
     * Solo se usa en caso de emergencia o ajustes administrativos.
     */
    function withdrawRemainingTokens() external onlyOwner {
        uint256 balance = IERC20(tokenContract).balanceOf(address(this));
        IERC20(tokenContract).transfer(owner, balance);
    }
}

interface IERC20 {
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

